#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<int>> g(n + 1);
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    int s, t;
    cin >> s >> t;

    vector<int> dist(n + 1, -1), par(n + 1, 0);   // -1 = nieodwiedzony
    queue<int> q;
    dist[s] = 0;
    q.push(s);
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        for (int u : g[v]) {
            if (dist[u] == -1) {          // oznaczamy PRZY WRZUCANIU do kolejki
                dist[u] = dist[v] + 1;
                par[u] = v;
                q.push(u);
            }
        }
    }

    if (dist[t] == -1) {
        cout << "NIE\n";
        return 0;
    }
    cout << dist[t] << '\n';
    vector<int> path;
    for (int v = t; v != s; v = par[v]) path.push_back(v);
    path.push_back(s);
    reverse(path.begin(), path.end());
    for (int v : path) cout << v << ' ';
    cout << '\n';
}

vector<int> bfs(const vector<vector<int>>& g, int s) {
    vector<int> dist(g.size(), -1);
    queue<int> q;
    dist[s] = 0;
    q.push(s);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (int u : g[v])
            if (dist[u] == -1) {
                dist[u] = dist[v] + 1;
                q.push(u);
            }
    }
    return dist;
}

vector<int> multiBfs(const vector<vector<int>>& g, const vector<int>& zrodla) {
    vector<int> dist(g.size(), -1);
    queue<int> q;
    for (int s : zrodla) {           // wszystkie źródła mają odległość 0
        if (dist[s] == -1) { dist[s] = 0; q.push(s); }
    }
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (int u : g[v])
            if (dist[u] == -1) { dist[u] = dist[v] + 1; q.push(u); }
    }
    return dist;                     // dist[v] = odległość do NAJBLIŻSZEGO źródła
}

