// 0-1 BFS: O(n + m), tylko wagi 0/1
vector<ll> zeroJeden(const vector<vector<pair<int,int>>>& g, int s) {
    vector<ll> d(g.size(), LLONG_MAX / 4);
    deque<int> dq;
    d[s] = 0; dq.push_back(s);
    while (!dq.empty()) {
        int v = dq.front(); dq.pop_front();
        for (auto [u, w] : g[v])
            if (d[v] + w < d[u]) { d[u] = d[v] + w; if (w == 0) dq.push_front(u); else dq.push_back(u); }
    }
    return d;
}
// Dijkstra: O(m log n), dowolne wagi >= 0 — na grafie 0/1 da ten sam wynik
vector<ll> dijkstra(const vector<vector<pair<int,int>>>& g, int s) {
    vector<ll> d(g.size(), LLONG_MAX / 4);
    priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<>> pq;
    d[s] = 0; pq.push({0, s});
    while (!pq.empty()) {
        auto [dv, v] = pq.top(); pq.pop();
        if (dv > d[v]) continue;
        for (auto [u, w] : g[v]) if (dv + w < d[u]) { d[u] = dv + w; pq.push({d[u], u}); }
    }
    return d;
}

