#include <bits/stdc++.h>
using namespace std;

const int MAXN = 200005;
vector<int> g[MAXN];
bool vis[MAXN];
int tin[MAXN], tout[MAXN], timer_ = 0;
vector<int> order;

void dfs(int v) {
    vis[v] = true;
    tin[v] = timer_++;          // czas wejścia
    order.push_back(v);         // preorder
    for (int u : g[v])
        if (!vis[u]) dfs(u);
    tout[v] = timer_++;         // czas wyjścia (postorder)
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    dfs(1);
    for (int v : order) cout << v << ' ';
    cout << '\n';
    int osiagalne = order.size();
    cout << "osiągalne z 1: " << osiagalne << '\n';
}

// Iteracyjny DFS z indeksem „następnego sąsiada” — ta sama kolejność co rekurencja,
// obsługuje też postorder (moment wyjścia). Bezpieczny dla n = 10^6.
vector<int> dfsIter(const vector<vector<int>>& g, int s, vector<int>& post) {
    int n = g.size();
    vector<int> pre, it(n, 0);
    vector<bool> vis(n, false);
    vector<int> st = {s};
    vis[s] = true;
    pre.push_back(s);
    while (!st.empty()) {
        int v = st.back();
        if (it[v] < (int)g[v].size()) {
            int u = g[v][it[v]++];
            if (!vis[u]) {
                vis[u] = true;
                pre.push_back(u);       // wejście do u
                st.push_back(u);
            }
        } else {
            post.push_back(v);          // wyjście z v
            st.pop_back();
        }
    }
    return pre;
}

