const int MAXN = 100005;
int p[MAXN], parity[MAXN], sz[MAXN];
void init(int n) { for (int i = 1; i <= n; i++) { p[i] = i; parity[i] = 0; sz[i] = 1; } }
pair<int, int> find(int x) {          // (korzeń, parzystość x względem korzenia)
    if (p[x] == x) return {x, 0};
    auto [r, q] = find(p[x]);
    parity[x] ^= q;
    p[x] = r;
    return {r, parity[x]};
}
bool addEdge(int a, int b) {          // false = graf przestaje być dwudzielny
    auto [ra, pa] = find(a);
    auto [rb, pb] = find(b);
    if (ra == rb) return pa != pb;
    if (sz[ra] < sz[rb]) { swap(ra, rb); swap(pa, pb); }
    p[rb] = ra;
    parity[rb] = pa ^ pb ^ 1;         // a i b mają mieć różne kolory
    sz[ra] += sz[rb];
    return true;
}

