#include <bits/stdc++.h>
using namespace std;

// Dzbanki o pojemnościach A i B. Operacje: napełnij, wylej, przelej jeden do drugiego.
// Minimalna liczba operacji, by w którymś dzbanku było dokładnie C litrów.
int main() {
    int A, B, C;
    cin >> A >> B >> C;
    auto id = [&](int a, int b) { return a * (B + 1) + b; };   // stan (a, b) -> liczba
    vector<int> dist((A + 1) * (B + 1), -1);
    queue<pair<int, int>> q;
    dist[id(0, 0)] = 0;
    q.push({0, 0});
    while (!q.empty()) {
        auto [a, b] = q.front(); q.pop();
        int d = dist[id(a, b)];
        if (a == C || b == C) { cout << d << '\n'; return 0; }
        int p1 = min(a, B - b), p2 = min(b, A - a);            // ile da się przelać
        pair<int, int> nast[6] = {{A, b}, {a, B}, {0, b}, {a, 0},
                                  {a - p1, b + p1}, {a + p2, b - p2}};
        for (auto [na, nb] : nast) {
            if (dist[id(na, nb)] == -1) {
                dist[id(na, nb)] = d + 1;
                q.push({na, nb});
            }
        }
    }
    cout << -1 << '\n';
}

// Labirynt z kluczami a..d i drzwiami A..D: stan = (x, y, maska zebranych kluczy).
int dx[] = {-1, 0, 1, 0}, dy[] = {0, 1, 0, -1};
int najkrotszaZKluczami(const vector<string>& s, int sx, int sy, int ex, int ey) {
    int n = s.size(), m = s[0].size(), K = 4;
    vector<int> dist(n * m << K, -1);
    auto id = [&](int x, int y, int mask) { return ((x * m + y) << K) | mask; };
    queue<array<int, 3>> q;
    dist[id(sx, sy, 0)] = 0;
    q.push({sx, sy, 0});
    while (!q.empty()) {
        auto [x, y, mask] = q.front(); q.pop();
        int d = dist[id(x, y, mask)];
        if (x == ex && y == ey) return d;
        for (int k = 0; k < 4; k++) {
            int nx = x + dx[k], ny = y + dy[k];
            if (nx < 0 || ny < 0 || nx >= n || ny >= m) continue;
            char c = s[nx][ny];
            if (c == '#') continue;
            if (c >= 'A' && c <= 'D' && !(mask >> (c - 'A') & 1)) continue;  // brak klucza
            int nm = mask;
            if (c >= 'a' && c <= 'd') nm |= 1 << (c - 'a');                 // podnosimy klucz
            if (dist[id(nx, ny, nm)] != -1) continue;
            dist[id(nx, ny, nm)] = d + 1;
            q.push({nx, ny, nm});
        }
    }
    return -1;
}

