// Szablon BFS po stanach: stan zakodowany jako int 0..S-1, ruchy generuje funkcja.
vector<int> ruchy(int s, int S) {             // przykład: z s można przejść do s+1 albo 2s (mod S)
    return {(s + 1) % S, (s * 2) % S};
}
int bfsStany(int start, int cel, int S) {
    vector<int> dist(S, -1);
    queue<int> q;
    dist[start] = 0;
    q.push(start);
    while (!q.empty()) {
        int s = q.front(); q.pop();
        if (s == cel) return dist[s];
        for (int t : ruchy(s, S))
            if (dist[t] == -1) { dist[t] = dist[s] + 1; q.push(t); }
    }
    return -1;                                 // stan celu nieosiągalny
}

