// Przesuwanka 2x3: stan jako string, '0' = puste pole
string start = "123405", cel = "123450";
unordered_map<string, int> dist;
queue<string> q;
dist[start] = 0; q.push(start);
int dr[] = {-1, 0, 1, 0}, dc[] = {0, 1, 0, -1};
while (!q.empty()) {
    string s = q.front(); q.pop();
    if (s == cel) break;
    int z = s.find('0'), r = z / 3, c = z % 3;
    for (int k = 0; k < 4; k++) {
        int nr = r + dr[k], nc = c + dc[k];
        if (nr < 0 || nr >= 2 || nc < 0 || nc >= 3) continue;
        string t = s;
        swap(t[z], t[nr * 3 + nc]);
        if (!dist.count(t)) { dist[t] = dist[s] + 1; q.push(t); }
    }
}
cout << dist[cel] << '\n';   // 1

// Graf jawny dla ilustracji: ścieżka 1-2-3-4-5
vector<vector<int>> g = {{}, {2}, {1, 3}, {2, 4}, {3, 5}, {4}};
int s = 1, t = 5, n = 5;
vector<int> ds(n + 1, -1), dt(n + 1, -1);
queue<int> qs, qt;
ds[s] = 0; qs.push(s); dt[t] = 0; qt.push(t);
int wynik = (s == t) ? 0 : -1;
auto krok = [&](queue<int>& q, vector<int>& d, vector<int>& inne) {
    int sz = q.size();
    while (sz--) {
        int v = q.front(); q.pop();
        for (int u : g[v]) {
            if (inne[u] != -1) return d[v] + 1 + inne[u];
            if (d[u] == -1) { d[u] = d[v] + 1; q.push(u); }
        }
    }
    return -1;
};
while (wynik == -1 && !qs.empty() && !qt.empty())
    wynik = (qs.size() <= qt.size()) ? krok(qs, ds, dt) : krok(qt, dt, ds);
cout << wynik << '\n';   // 4

int n = 2, m = 2;
vector<string> s = {"..", ".."};
int dx[] = {-1, 0, 1, 0}, dy[] = {0, 1, 0, -1};
vector<int> dist(n * m * 4, -1);
auto id = [&](int x, int y, int k) { return (x * m + y) * 4 + k; };
queue<array<int,3>> q;
dist[id(0, 0, 1)] = 0; q.push({0, 0, 1});            // start w (0,0), patrzy w prawo
while (!q.empty()) {
    auto [x, y, k] = q.front(); q.pop();
    int d = dist[id(x, y, k)];
    array<array<int,3>,3> nxt = {{{x, y, (k + 1) % 4}, {x, y, (k + 3) % 4},
                                  {x + dx[k], y + dy[k], k}}};
    for (auto [nx, ny, nk] : nxt) {
        if (nx < 0 || ny < 0 || nx >= n || ny >= m || s[nx][ny] == '#') continue;
        if (dist[id(nx, ny, nk)] == -1) { dist[id(nx, ny, nk)] = d + 1; q.push({nx, ny, nk}); }
    }
}
int best = INT_MAX;
for (int k = 0; k < 4; k++) if (dist[id(1, 1, k)] != -1) best = min(best, dist[id(1, 1, k)]);
cout << best << '\n';   // 3: krok, obrót, krok
